{
  "property_address": "Flat No. 302, Green Residency, Sector 62, Noida, Uttar Pradesh.",
  "tenant_name": "Priya Verma",
  "landlord_name": "Rajesh Sharma",
  "lease_start_date": "1 April 2025",
  "lease_end_date": "31 March 2026",
  "monthly_rent": "Rs. 25,000",
  "security_deposit": "Rs. 50,000",
  "utilities": {
    "tenant_pays": [
      "Utility bills up to move-out"
    ],
    "landlord_pays": []
  },
  "move_out_cleaning_required": true,
  "professional_cleaning_required": false,
  "painting_required": false,
  "tenant_responsible_for_damage": true,
  "tenant_responsible_for_fixtures": false,
  "late_fees": null,
  "other_obligations": [
    "Tenant shall return all keys before final inspection."
  ],
  "clauses": [
    {
      "id": "clause_1",
      "title": "Security deposit refund",
      "text": "Security deposit shall be refunded within 30 days after vacating, subject only to legitimate deductions supported by evidence."
    },
    {
      "id": "clause_2",
      "title": "Normal wear and tear",
      "text": "Normal wear and tear, including minor paint fading, small nail holes, and ordinary flooring wear, shall not be charged to the tenant."
    },
    {
      "id": "clause_3",
      "title": "Deductions for actual damage",
      "text": "Landlord may deduct amounts only for actual damage beyond normal wear and tear."
    },
    {
      "id": "clause_4",
      "title": "Evidence for deductions",
      "text": "Every deduction must be supported by invoices, repair receipts, photographs, or quotations."
    },
    {
      "id": "clause_5",
      "title": "Cleaning charges",
      "text": "Cleaning charges may be deducted only if the premises are left in an unusually unhygienic condition."
    },
    {
      "id": "clause_6",
      "title": "Key return",
      "text": "Tenant shall return all keys before final inspection."
    },
    {
      "id": "clause_7",
      "title": "Utility bills responsibility",
      "text": "Utility bills up to move-out remain the tenant's responsibility."
    },
    {
      "id": "clause_8",
      "title": "Jurisdiction",
      "text": "Jurisdiction: Noida, Uttar Pradesh."
    }
  ]
}
